#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, datetime as dt, os, py_compile, shutil, subprocess, sys
from pathlib import Path
VERSION='0.10.0'
MODIFIED_B64={'backend/app/api/v1/endpoints/vision_app_api.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/models.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/runtime.py': {'old': '', 'new': ''}, 'backend/tests/vision_app/test_vision_app_v0800.py': {'old': '', 'new': ''}, 'frontend/src/Pages/ComputerVisionPage.tsx': {'old': '', 'new': ''}, 'frontend/src/api/visionAppApi.ts': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/ComputerVision.css': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/DebugWorkspace.tsx': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/ScopeEditorModal.tsx': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/WorkingModulePanel.tsx': {'old': '', 'new': ''}, 'frontend/tools/generate_llm_context_map.py': {'old': '', 'new': ''}}
CREATED_B64={'backend/tests/vision_app/test_vision_app_v1000.py': '', 'frontend/docs/llm_context/updates/v1000_computer_vision_scope_debug_stack.md': ''}
MODIFIED={k:{'old':base64.b64decode(v['old']).decode(),'new':base64.b64decode(v['new']).decode()} for k,v in MODIFIED_B64.items()}
CREATED={k:base64.b64decode(v).decode() for k,v in CREATED_B64.items()}

def roots(f=None,b=None):
    c=Path.cwd().resolve();fs=[];bs=[]
    if f:fs.append(Path(f).expanduser().resolve())
    if b:bs.append(Path(b).expanduser().resolve())
    fs += [c,c/'LambdaVisionSuper',c.parent/'LambdaVisionSuper']
    bs += [c,c/'LambdaVisionSuperBackEnd',c.parent/'LambdaVisionSuperBackEnd']
    fe=next((p for p in fs if (p/'src/Pages/ComputerVisionPage.tsx').exists()),None)
    be=next((p for p in bs if (p/'app/services/vision_app/models.py').exists()),None)
    if not fe:raise RuntimeError('Cannot locate LambdaVisionSuper frontend. Use --frontend /path/to/LambdaVisionSuper')
    if not be:raise RuntimeError('Cannot locate LambdaVisionSuperBackEnd. Use --backend /path/to/LambdaVisionSuperBackEnd')
    return fe,be

def path(fe,be,v):return (fe/v[9:]) if v.startswith('frontend/') else (be/v[8:])
def mstate(p,o,n):
    if not p.exists():return 'MISSING'
    s=p.read_text(encoding='utf-8');return 'OK' if s==n else 'UPDATE' if s==o else 'CONFLICT'
def cstate(p,n):
    if not p.exists():return 'CREATE'
    return 'OK' if p.read_text(encoding='utf-8')==n else 'CONFLICT'

def scan(fe,be):
    print('='*104);print('COMPUTER VISION V0.10.0 — SCOPE QUICK CONTROLS + DEBUG STACK WORKSPACE');print('='*104);print('Frontend :',fe);print('Backend  :',be);print()
    bad=0
    for v,x in MODIFIED.items():
        s=mstate(path(fe,be,v),x['old'],x['new']);print(f'  [{s:12}] {v}');bad+=s in ('MISSING','CONFLICT')
    for v,n in CREATED.items():
        s=cstate(path(fe,be,v),n);print(f'  [{s:12}] {v}');bad+=s=='CONFLICT'
    print('\nv0.10 contract:')
    print('  New Scope defaults: Filter enabled + Logic enabled; Decision remains future-IDE ownership')
    print('  Operation scope uses expandable Filter/Logic quick controls with inline stack adjustment')
    print('  Decision / Glue removed completely from Scope UI')
    print('  One Debug Stack Workspace for full inspection AND Filter-stack preview')
    print('  Debug stack: grouped pipeline stages, Prev/Next, zoom/pan image, Logic output inspector, benchmark trace')
    print('  Debug image bytes lazy-load on selection and cache only for the current debug session')
    print('  Filter preview API returns benchmark trace; embedded Filter Debug View is removed')
    print('  Context generator + v0.10 handoff MD included')
    if bad:print(f'[WARN] {bad} conflict/base issue(s); apply will stop safely.')
    return 0

def pre(fe,be):
    e=[]
    for v,x in MODIFIED.items():
        s=mstate(path(fe,be,v),x['old'],x['new'])
        if s not in ('UPDATE','OK'):e.append(f'{v}: {s}')
    for v,n in CREATED.items():
        s=cstate(path(fe,be,v),n)
        if s not in ('CREATE','OK'):e.append(f'{v}: {s}')
    if e:raise RuntimeError('Safe update stopped:\n  - '+'\n  - '.join(e))

def regen(fe,be):
    g=fe/'tools/generate_llm_context_map.py'
    if not g.exists():print('[SKIP] Context generator not found');return
    cmd=[sys.executable,str(g),'--frontend',str(fe),'--backend',str(be)]
    if '--output-dir' in g.read_text(encoding='utf-8'):cmd += ['--output-dir',str(fe/'docs/llm_context')]
    p=subprocess.run(cmd,cwd=str(fe),text=True,capture_output=True)
    if p.returncode:raise RuntimeError('Context generation failed:\n'+p.stdout+'\n'+p.stderr)
    if p.stdout.strip():print(p.stdout.strip())

def apply(fe,be):
    pre(fe,be);stamp=dt.datetime.now().strftime('%Y%m%d_%H%M%S');bak=fe/'.lambda_updater_backups'/f'computer_vision_v1000_{stamp}';bak.mkdir(parents=True,exist_ok=True)
    for v in list(MODIFIED)+list(CREATED):
        p=path(fe,be,v)
        if p.exists():
            q=bak/v;q.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,q)
    for v,x in MODIFIED.items():
        p=path(fe,be,v)
        if p.read_text(encoding='utf-8')!=x['new']:p.write_text(x['new'],encoding='utf-8');print('[WRITE]',v)
    for v,n in CREATED.items():
        p=path(fe,be,v);p.parent.mkdir(parents=True,exist_ok=True)
        if not p.exists() or p.read_text(encoding='utf-8')!=n:p.write_text(n,encoding='utf-8');print('[WRITE]',v)
    print('[INFO] Regenerating LLM context docs...');regen(fe,be);print('[OK] Backup:',bak);print('Run verify next.');return 0

def tscheck(fe):
    files=[str(path(fe,Path('/unused'),v)) for v in list(MODIFIED)+list(CREATED) if v.startswith('frontend/') and v.endswith(('.ts','.tsx'))]
    js='''const fs=require("fs"),ts=require("typescript");let bad=0;for(const f of process.argv.slice(1)){const r=ts.transpileModule(fs.readFileSync(f,"utf8"),{fileName:f,reportDiagnostics:true,compilerOptions:{jsx:ts.JsxEmit.ReactJSX,target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.ESNext}});for(const d of r.diagnostics||[])if(d.category===ts.DiagnosticCategory.Error){bad++;console.error(f,ts.flattenDiagnosticMessageText(d.messageText,"\\n"));}}process.exit(bad?1:0);'''
    env=dict(os.environ);r=subprocess.run(['npm','root','-g'],text=True,capture_output=True)
    if r.returncode==0 and r.stdout.strip():env['NODE_PATH']=r.stdout.strip()
    return subprocess.run(['node','-e',js,*files],cwd=str(fe),env=env,text=True,capture_output=True)

def verify(fe,be,skip=False):
    print('='*104);print('VERIFY COMPUTER VISION V0.10.0');print('='*104);fail=0
    working=(fe/'src/components/ComputerVision/WorkingModulePanel.tsx').read_text(encoding='utf-8')
    editor=(fe/'src/components/ComputerVision/ScopeEditorModal.tsx').read_text(encoding='utf-8')
    debug=(fe/'src/components/ComputerVision/DebugWorkspace.tsx').read_text(encoding='utf-8')
    page=(fe/'src/Pages/ComputerVisionPage.tsx').read_text(encoding='utf-8')
    model=(be/'app/services/vision_app/models.py').read_text(encoding='utf-8')
    runtime=(be/'app/services/vision_app/runtime.py').read_text(encoding='utf-8')
    api=(be/'app/api/v1/endpoints/vision_app_api.py').read_text(encoding='utf-8')
    checks=[
      ('Filter/Logic enabled by default','enable_filter: bool = True' in model and 'enable_logic: bool = True' in model),
      ('Expandable Scope quick controls','Open Stack Workspace' in working and 'Debug Filter Stack' in working and 'ChevronDown' in working),
      ('Inline quick service adjustment','addQuick' in working and 'quickChoice' in working and 'Output alias' in working and 'moveBinding' in working),
      ('Decision / Glue removed from Scope UI','Decision / Glue' not in working and "type Phase='filter'|'logic'" in editor),
      ('Unified Debug Stack Workspace','DEBUG STACK WORKSPACE' in debug and 'PIPELINE STACK' in debug and 'LOGIC OUTPUT INSPECTOR' in debug),
      ('Debug Prev/Next stage navigation','Prev' in debug and 'Next' in debug and 'currentIndex' in debug),
      ('Lazy image artifact loading','images lazy-load on selection' in debug and 'cache' in debug and 'await load(runId' in debug),
      ('Filter preview uses unified Debug Stack','previewScopeDebug' in page and 'debugSession' in page and 'Preview Stack in Debug Workspace' in editor),
      ('Filter preview returns benchmark trace','benchmarks: list[BenchmarkStep]' in runtime and '"benchmarks": [model_to_dict(item) for item in benchmarks]' in api),
      ('v0.10 handoff MD',(fe/'docs/llm_context/updates/v1000_computer_vision_scope_debug_stack.md').exists()),
      ('Context generator v0.10','unified lazy Debug Stack Workspace' in (fe/'tools/generate_llm_context_map.py').read_text(encoding='utf-8')),
    ]
    for l,o in checks:print(f'[{"OK" if o else "FAIL"}] {l}');fail+=0 if o else 1
    py=[path(fe,be,v) for v in list(MODIFIED)+list(CREATED) if v.startswith('backend/') and v.endswith('.py')]
    try:
        for p in py:py_compile.compile(str(p),doraise=True)
        print(f'[OK] Python syntax ({len(py)} changed/new backend files)')
    except Exception as e:print('[FAIL] Python syntax',e);fail+=1
    full_ready=(be/'app/core/config.py').exists() and (be/'app/services/vision_labs/image/types.py').exists()
    if full_ready:
        cmd=[sys.executable,'-m','pytest','-q','tests/vision_app']
    else:
        targets=[x for x in ['tests/vision_app/test_vision_app_v0900.py','tests/vision_app/test_vision_app_v1000.py'] if (be/x).exists()]
        cmd=[sys.executable,'-m','pytest','-q',*targets]
        print('[INFO] Reduced mock regression set: full app/core + vision_labs are not present in this checkout.')
    p=subprocess.run(cmd,cwd=str(be),text=True,capture_output=True)
    if p.returncode==0:print('[OK] Vision App regression tests');print(p.stdout.strip())
    else:print('[FAIL] Vision App regression tests');print((p.stdout+'\n'+p.stderr).strip());fail+=1
    t=tscheck(fe)
    if t.returncode==0:print('[OK] TypeScript syntax/transpile')
    else:print('[FAIL] TypeScript syntax/transpile');print((t.stdout+'\n'+t.stderr).strip());fail+=1
    if not skip and (fe/'node_modules').exists():
        p=subprocess.run(['npm','run','build'],cwd=str(fe))
        if p.returncode==0:print('[OK] Frontend npm build')
        else:print('[FAIL] Frontend npm build');fail+=1
    else:print('[SKIP] Frontend npm build')
    try:
        regen(fe,be)
        arch=fe/'docs/llm_context/SYSTEM_ARCHITECTURE.md'
        ok=not arch.exists() or ('Computer Vision' in arch.read_text(encoding='utf-8') and 'Debug Stack' in arch.read_text(encoding='utf-8'))
        print(f'[{"OK" if ok else "FAIL"}] Regenerated LLM context docs')
        fail+=0 if ok else 1
    except Exception as e:print('[FAIL] Context regeneration',e);fail+=1
    if fail:print(f'[FAIL] v0.10.0 verification finished with {fail} issue(s).');return 1
    print('[OK] Computer Vision v0.10.0 verified.');return 0

def main():
    p=argparse.ArgumentParser();p.add_argument('command',choices=['scan','apply','verify']);p.add_argument('--frontend');p.add_argument('--backend');p.add_argument('--skip-build',action='store_true');a=p.parse_args()
    try:
        fe,be=roots(a.frontend,a.backend)
        return scan(fe,be) if a.command=='scan' else apply(fe,be) if a.command=='apply' else verify(fe,be,a.skip_build)
    except Exception as e:print('[ERROR]',e);return 2
if __name__=='__main__':raise SystemExit(main())
